import { remoteAction, remoteEvent, remoteQuery, ServiceClient } from "@stackra/clients";
import { HttpMethod } from "@stackra/contracts";
import { currencyCode, publicId } from "@stackra/validation/runtime";
import { z } from "zod";

/** pricing: the shapes and descriptors of the calls commerce makes. */
export namespace Pricing {
  /** `pricing.price.quote@1` input. */
  export const QuoteInput$ = z.object({
    market: z.string(),
    lines: z.array(z.object({ variantId: publicId("var"), quantity: z.number().int() })),
  });

  /** `pricing.price.quote@1` output: unit prices in minor units of one currency. */
  export const QuoteOutput$ = z.object({
    currency: currencyCode(),
    lines: z.array(
      z.object({
        variantId: publicId("var"),
        quantity: z.number().int(),
        unitPriceMinor: z.number().int(),
      }),
    ),
  });

  /** The quote's output as the caller reads it. */
  export type QuoteOutput = z.output<typeof QuoteOutput$>;

  /** `pricing.price.quote@1`, `POST /prices/quote`. */
  export const Quote = remoteQuery("pricing.price.quote@1", {
    input: QuoteInput$,
    output: QuoteOutput$,
    endpoint: { method: HttpMethod.Post, path: "/prices/quote" },
  });
}

/** payments: both actions run under the on-behalf-of chain. */
export namespace Payments {
  /** `payments.payment.authorize@1` input; `reference` is the caller's id (an order id here). */
  export const AuthorizeInput$ = z.object({
    reference: z.string(),
    amountMinor: z.number().int(),
    currency: z.string(),
  });

  /** `payments.payment.authorize@1` output. */
  export const AuthorizeOutput$ = z.object({ paymentId: z.string(), clientSecret: z.string() });

  /** What an authorization returns; CreateOrderWorkflow stores it as a step result. */
  export type AuthorizeOutput = z.output<typeof AuthorizeOutput$>;

  /** `payments.payment.void@1` input and output. */
  export const VoidInput$ = z.object({ paymentId: z.string() });

  /** `payments.payment.authorize@1`, `POST /payments`. */
  export const Authorize = remoteAction("payments.payment.authorize@1", {
    input: AuthorizeInput$,
    output: AuthorizeOutput$,
    endpoint: { method: HttpMethod.Post, path: "/payments" },
  });

  /** `payments.payment.void@1`, `PUT /payments/:paymentId/void`. */
  export const Void = remoteAction("payments.payment.void@1", {
    input: VoidInput$,
    output: VoidInput$,
    endpoint: { method: HttpMethod.Put, path: "/payments/:paymentId/void" },
  });

  /** `payments.payment.captured.v1`; `reference` is whatever the authorizer passed. */
  export class PaymentCaptured extends remoteEvent(
    "payments.payment.captured.v1",
    z.object({
      paymentId: z.string(),
      reference: z.string(),
      amountMinor: z.number().int(),
      currency: z.string(),
    }),
  ) {}

  /** `payments.payment.failed.v1`; `reason` is the provider's snake_case code. */
  export class PaymentFailed extends remoteEvent(
    "payments.payment.failed.v1",
    z.object({ paymentId: z.string(), reference: z.string(), reason: z.string() }),
  ) {}
}

/** notifications: the delivery service the `notifications` Notifier driver queues into. */
export namespace Notifications {
  /** `messages.message.send@1` input: the rendered parts of one message. */
  export const SendInput$ = z.object({
    mail: z.string().regex(/^[a-z][a-z0-9_]*$/),
    to: z.object({ principalId: publicId("usr") }),
    subject: z.string().min(1).max(200),
    html: z.string().min(1),
    text: z.string().min(1),
  });

  /** `messages.message.send@1`, `POST /messages`. */
  export const Send = remoteAction("messages.message.send@1", {
    input: SendInput$,
    output: z.object({ messageId: publicId("msg") }),
    endpoint: { method: HttpMethod.Post, path: "/messages" },
  });
}

/** Calls into the pricing service; `price.quote.call(input)` is authoritative now. */
export class PricingClient extends ServiceClient {
  /** The `price` resource. */
  readonly price = { quote: this.member(Pricing.Quote) };
}

/** Calls into the payments service; `void` is also `.queue(input)`, a queued call. */
export class PaymentsClient extends ServiceClient {
  /** The `payment` resource. */
  readonly payment = {
    authorize: this.member(Payments.Authorize),
    void: this.member(Payments.Void),
  };
}

/** Calls into the notifications service; the `notifications` Notifier driver uses `.queue`. */
export class NotificationsClient extends ServiceClient {
  /** The `message` resource. */
  readonly message = { send: this.member(Notifications.Send) };
}
